import { constantTimeEqual } from './constantTime.ts';
import { applyOwnerCapabilities } from './ownerRole.ts';

// Short-lived auth cache — every function call used to spend ~2 entity_list
// reads re-verifying the same session (AuthorizedEmail + UserSession). Deno
// isolates persist across invocations, so a 60s cache eliminates the
// per-invoke read cost on warm isolates while keeping session revocation
// near-immediate. Only successful authentications are cached.
const sessionAuthCache = new Map<string, { user: any; expires: number }>();
const SESSION_AUTH_CACHE_MS = 60_000;

function b64urlEncode(str: string) {
  return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function b64urlDecode(str: string) {
  let value = String(str || '').replace(/-/g, '+').replace(/_/g, '/');
  while (value.length % 4) value += '=';
  return atob(value);
}

async function hmacSign(message: string, secret: string) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(message));
  return b64urlEncode(String.fromCharCode(...new Uint8Array(sig)));
}

export async function signShopSessionPayload(payload: Record<string, unknown>) {
  const secret = Deno.env.get('SESSION_SIGNING_SECRET');
  if (!secret) throw Object.assign(new Error('Session authentication is unavailable'), { status: 503 });

  const payloadStr = b64urlEncode(JSON.stringify(payload));
  const sig = await hmacSign(payloadStr, secret);
  return `${payloadStr}.${sig}`;
}

export async function signShopSessionTokenHash(token: string) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(token));
  return b64urlEncode(String.fromCharCode(...new Uint8Array(buf)));
}

export async function authenticateSignShopSession(base44: any, token: unknown) {
  const rawToken = String(token || '').trim();
  if (!rawToken) throw Object.assign(new Error('Authentication required'), { status: 401 });

  const parts = rawToken.split('.');
  if (parts.length !== 2) throw Object.assign(new Error('Authentication required'), { status: 401 });

  const secret = Deno.env.get('SESSION_SIGNING_SECRET');
  if (!secret) throw Object.assign(new Error('Session authentication is unavailable'), { status: 503 });

  const [payloadStr, providedSig] = parts;
  const expectedSig = await hmacSign(payloadStr, secret);
  if (!constantTimeEqual(expectedSig, providedSig)) throw Object.assign(new Error('Authentication required'), { status: 401 });

  let sessionPayload: any;
  try {
    sessionPayload = JSON.parse(b64urlDecode(payloadStr));
  } catch {
    throw Object.assign(new Error('Authentication required'), { status: 401 });
  }

  const email = String(sessionPayload?.email || '').trim().toLowerCase();
  const issuedAt = Number(sessionPayload?.iat);
  const expiresAt = Number(sessionPayload?.exp);
  if (
    !email ||
    !Number.isFinite(issuedAt) || issuedAt <= 0 ||
    !Number.isFinite(expiresAt) || expiresAt <= Date.now() || expiresAt <= issuedAt
  ) {
    throw Object.assign(new Error('Authentication required'), { status: 401 });
  }

  // Break-glass expiry — a time-boxed admin grant lapses automatically; the
  // actor keeps their session but every backend admin gate sees a non-admin.
  const stripExpiredGrant = (user: any) => {
    const grantExpiry = Date.parse(String(user?.admin_grant_expires || ''));
    if (Number.isFinite(grantExpiry) && grantExpiry > 0 && grantExpiry <= Date.now() && user) {
      user.role = 'user';
      user.is_full_admin = false;
      user.admin_permissions = {};
    }
    return user;
  };

  const tokenHash = await signShopSessionTokenHash(rawToken);
  const cachedAuth = sessionAuthCache.get(tokenHash);
  if (cachedAuth && cachedAuth.expires > Date.now()) return applyOwnerCapabilities(stripExpiredGrant(cachedAuth.user));

  const users = await base44.asServiceRole.entities.AuthorizedEmail.filter({ email });
  if (!Array.isArray(users)) {
    throw Object.assign(new Error('Authenticated user identity could not be verified'), { status: 503 });
  }
  if (users.length === 0) throw Object.assign(new Error('Authentication required'), { status: 401 });
  if (users.length !== 1) {
    throw Object.assign(new Error('Authenticated user identity is ambiguous'), { status: 409 });
  }

  // Revocation check — a revoked UserSession row (by token fingerprint) rejects this token.
  try {
    const revoked = await base44.asServiceRole.entities.UserSession.filter({ token_hash: tokenHash, revoked: true });
    if (Array.isArray(revoked) && revoked.length > 0) {
      throw Object.assign(new Error('Authentication required'), { status: 401 });
    }
  } catch (e) {
    if (e?.status === 401) throw e;
    // UserSession may not exist yet — treat lookup failures as non-blocking.
  }

  // Owner normalization runs AFTER grant-expiry strip — an owner (anchored or
  // granted) is never demoted by a lapsed break-glass grant.
  const user = applyOwnerCapabilities(stripExpiredGrant(users[0]));
  if (sessionAuthCache.size > 500) sessionAuthCache.clear();
  sessionAuthCache.set(tokenHash, { user, expires: Date.now() + SESSION_AUTH_CACHE_MS });
  const notBefore = Date.parse(String(user?.session_not_before || ''));
  if (Number.isFinite(notBefore) && notBefore > 0 && (!Number.isFinite(issuedAt) || issuedAt < notBefore)) {
    throw Object.assign(new Error('Authentication required'), { status: 401 });
  }

  return user;
}

import { traceDelay } from './smartsheetTraceContext.ts';

// Per-isolate entity-call counters. Every asServiceRole entity call wrapped by
// this module increments these; module state persists across warm invocations
// on the same isolate, so functions can read the delta across one invocation
// (calls-per-action) and the load harness can sample the aggregate spend.
const isolateEntityStats = {
  calls: 0,        // total entity API attempts (incl. retries)
  retries: 0,      // attempts that were 429 retries (not new logical calls)
  paced_waits: 0,  // times a caller waited on the paceMs queue
  since: new Date().toISOString(),
};
export function entityCallIsolateStats() { return { ...isolateEntityStats }; }

// Base44's own database API also rate-limits ("Rate limit exceeded"). Retry those
// calls with backoff so one burst does not skip a whole sync stage.
// maxRetries defaults to the historical 5 so background callers are unchanged;
// interactive gateways pass a small value and let the browser back off instead
// of stacking server-side and client-side retry delays.
export function withEntityRateLimitRetry(client: any, { paceMs = 0, maxRetries = 5 } = {}) {
  if (!client?.asServiceRole?.entities) return client;
  // One queue across all entities in this sync invocation, including parallel reads.
  let queue = Promise.resolve();
  let nextRequestAt = 0;
  const reserveRequest = () => {
    const slot = queue.then(async () => {
      const delay = nextRequestAt - Date.now();
      if (delay > 0) { const start = performance.now(); await new Promise(resolve => setTimeout(resolve, delay)); traceDelay('base44_pacing_wait', performance.now() - start); }
      nextRequestAt = Date.now() + paceMs;
    });
    queue = slot.catch(() => {});
    return slot;
  };
  const isLimited = (e: any) => e?.status === 429 || /rate limit|traffic volume/i.test(String(e?.message || e?.data?.message || ''));
  const wrapEntity = (entity: any) => new Proxy(entity, {
    get(target, prop) {
      const value = target[prop];
      if (typeof value !== 'function') return value;
      return async (...args: any[]) => {
        for (let attempt = 0; ; attempt++) {
          if (paceMs) { isolateEntityStats.paced_waits++; await reserveRequest(); }
          isolateEntityStats.calls++;
          if (attempt > 0) isolateEntityStats.retries++;
          try { return await value.apply(target, args); }
          catch (e) {
            if (!isLimited(e)) throw e;
            if (attempt >= maxRetries) {
              // Normalize the outgoing shape: catches across the functions map
              // error.status/statusCode to an HTTP status, but some SDK rate-
              // limit errors arrive message-only. Stamping 429 lets every
              // catch propagate a retryable status instead of flattening to 500.
              e.status = e.status ?? 429;
              e.statusCode = e.statusCode ?? 429;
              throw e;
            }
            // Background work yields longer instead of competing with employee access.
            const delay = paceMs ? 15000 * (attempt + 1) : 1500 * (attempt + 1);
            if (paceMs) nextRequestAt = Math.max(nextRequestAt, Date.now() + delay);
            const start = performance.now(); await new Promise((r) => setTimeout(r, delay)); traceDelay('base44_retry_wait', performance.now() - start, true);
          }
        }
      };
    },
  });
  const entities = new Proxy(client.asServiceRole.entities, {
    get: (target, name) => (target[name] ? wrapEntity(target[name]) : target[name]),
  });
  const serviceRole = new Proxy(client.asServiceRole, { get: (t, p) => (p === 'entities' ? entities : t[p]) });
  return new Proxy(client, { get: (t, p) => (p === 'asServiceRole' ? serviceRole : t[p]) });
}

const SYSTEM_FIELDS = new Set(['id', 'created_date', 'updated_date', 'created_by_id', 'created_by', 'edit_reason']);

export const estimateAuditNumber = (value: unknown, fallback = 0) =>
  Number.isFinite(Number(value)) ? Number(value) : fallback;

export function estimateAuditSnapshot(estimate: Record<string, any> = {}, overrides: { quoteTotal?: unknown; internalCost?: unknown } = {}) {
  const snapshot: Record<string, any> = {};
  for (const [key, value] of Object.entries(estimate || {})) {
    if (SYSTEM_FIELDS.has(key)) continue;
    snapshot[key] = value;
  }
  snapshot.total_cost = overrides.internalCost === undefined
    ? estimateAuditNumber(estimate?.total_cost)
    : estimateAuditNumber(overrides.internalCost);
  snapshot.quote_total = overrides.quoteTotal === undefined
    ? estimateAuditNumber(estimate?.quote_total)
    : estimateAuditNumber(overrides.quoteTotal);
  return JSON.parse(JSON.stringify(snapshot));
}

export function summarizeEstimateAuditChanges(before: Record<string, any> = {}, after: Record<string, any> = {}) {
  const changes: string[] = [];
  if (String(before.status || '') !== String(after.status || '')) {
    changes.push(`Status: ${before.status || 'draft'} → ${after.status || 'draft'}`);
  }
  if (estimateAuditNumber(before.quote_version) !== estimateAuditNumber(after.quote_version)) {
    changes.push(`Customer quote issued: Version ${estimateAuditNumber(after.quote_version)} · ${after.quote_issue_date || 'date not recorded'}`);
  }
  if (Math.abs(estimateAuditNumber(before.quote_total) - estimateAuditNumber(after.quote_total)) > 0.005) {
    changes.push(`Customer quote total: ${estimateAuditNumber(before.quote_total).toFixed(2)} → ${estimateAuditNumber(after.quote_total).toFixed(2)}`);
  }
  if (Math.abs(estimateAuditNumber(before.total_cost) - estimateAuditNumber(after.total_cost)) > 0.005) {
    changes.push(`Internal cost: ${estimateAuditNumber(before.total_cost).toFixed(2)} → ${estimateAuditNumber(after.total_cost).toFixed(2)}`);
  }
  if (JSON.stringify(before.line_items || []) !== JSON.stringify(after.line_items || [])) {
    changes.push('Product scope / Product pricing changed');
  }

  const quoteKeys = [
    'discount_percent', 'contingency_percent', 'tax_percent', 'deposit_percent', 'shipping_fee', 'permit_fee',
    'hide_section_prices', 'quote_title', 'quote_intro_text', 'scope_inclusions', 'scope_exclusions', 'payment_terms',
    'quote_terms_conditions', 'warranty_text', 'lead_time_text',
  ];
  if (quoteKeys.some((key) => JSON.stringify(before[key]) !== JSON.stringify(after[key]))) {
    changes.push('Customer quote settings / terms changed');
  }

  const detailKeys = [
    'project_name', 'client_name', 'customer_id', 'po_number', 'site_address', 'order_contact', 'contact_name',
    'contact_email', 'contact_phone', 'salesperson', 'target_install_date', 'priority', 'tags',
  ];
  if (detailKeys.some((key) => JSON.stringify(before[key]) !== JSON.stringify(after[key]))) {
    changes.push('Estimate / customer details changed');
  }

  return changes.length ? changes : ['Estimate saved with no material customer-facing change detected'];
}

export function estimateQuoteIssueKey(estimateId: unknown, quoteVersion: unknown) {
  const id = String(estimateId || '').trim();
  const version = Math.max(0, Math.floor(estimateAuditNumber(quoteVersion)));
  return id && version > 0 ? `estimate:${id}:quote:v${version}` : '';
}
